    need(re.search(rb'datasource\s+db\s*\{\s*provider\s*=\s*"postgresql"\s*\}',schema),'Unexpected datasource')
    pnpm=shutil.which('pnpm'); need(pnpm,'pnpm not available')
    psql=str(P(psql).resolve()); need(P(psql).is_file() and os.access(psql,os.X_OK),'psql not available')
    # Do not load application dotenv or inherited service credentials.
    env={k:v for k,v in os.environ.items() if k in ('PATH','LANG','LC_ALL','LC_CTYPE','TERM','SYSTEMROOT','HOME','TMPDIR')}
    env.update(CI='1',NEXT_TELEMETRY_DISABLED='1',PGCONNECT_TIMEOUT='5')
    pgenv=dict(env,PGPASSWORD=password)
    argv=[psql,'-X','-w','--host=127.0.0.1',f'--port={u.port}',f'--username={user}','-v','ON_ERROR_STOP=1','-At']
    def query(database,sql):
        p=subprocess.run(argv+[f'--dbname={database}','-c',sql],env=pgenv,cwd=root,capture_output=True,text=True,timeout=60)
        need(p.returncode==0,'PostgreSQL query failed; no automatic repair or retry');return p.stdout.strip()
    need(query('postgres','SELECT current_database()')=='postgres','Wrong maintenance database')
    cluster=query('postgres',"SELECT current_setting('data_directory')")
    need(bool(cluster),'Could not identify cluster')
    def identity():
        need(query(db,'SELECT current_database()')==db and query(db,"SELECT current_setting('data_directory')")==cluster,'Wrong target identity')
    need(query('postgres',f"SELECT count(*) FROM pg_database WHERE datname='{db}'")=='0','Target already exists; refusing all migration work')
    # CREATE DATABASE itself is an atomic additional existence guard. No DROP,
    # reset, or resolve is ever performed on an already-existing target.
    query('postgres',f'CREATE DATABASE "{db}" TEMPLATE template0');print('CREATED_NEW_DATABASE='+db,flush=True)
    identity()
    need(query(db,"SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public'")=='0','New public schema is not empty')
    need(query(db,"SELECT count(*) FROM pg_namespace WHERE nspname NOT IN ('public','information_schema','pg_catalog') AND nspname NOT LIKE 'pg_%'")=='0','Unexpected user schemas')
    dburl=urlunsplit((u.scheme,u.netloc,'/'+db,'schema=public',''))
    with tempfile.TemporaryDirectory(prefix='fresh-prisma-',dir=root) as t:
        cfgdir=P(t).resolve(); (cfgdir/'schema.prisma').write_bytes(schema)
        cfg=cfgdir/'prisma.config.ts';cfg.write_text('import { defineConfig, env } from "prisma/config";\nexport default defineConfig({ schema: "schema.prisma", migrations: { path: "migrations" }, datasource: { url: env("DATABASE_URL") } });\n')
        def materialize(selected):
            for p,b in files.items():
                if p=='migration_lock.toml' or P(p).parent.name in selected:
                    target=cfgdir/'migrations'/p;target.parent.mkdir(parents=True,exist_ok=True)
                    if target.exists(): need(target.read_bytes()==b,'Migration copy changed')
                    else: target.write_bytes(b)
        def prisma(label,*args):
            identity(); print('RUNNING='+label,flush=True)
            p=subprocess.run([pnpm,'exec','prisma',*args,'--config',str(cfg)],cwd=root,env=dict(env,DATABASE_URL=dburl),stdout=subprocess.PIPE,stderr=subprocess.STDOUT,timeout=1800)
            # Never expose the URL or secret in output, including encoded form.
            raw=p.stdout.decode(errors='replace').replace(dburl,'[redacted URL]').replace(password,'[redacted]').replace(u.password,'[redacted]')
            print(raw,flush=True);need(p.returncode==0,label+' failed; leave new database for inspection, do not retry blindly')
        def ledger(selected):
            identity();rows=query(db,'SELECT migration_name || chr(124) || checksum || chr(124) || (finished_at IS NOT NULL AND rolled_back_at IS NULL)::text FROM "_prisma_migrations" ORDER BY migration_name').splitlines()
            expected=sorted(f'{n}|{digest(files[n+"/migration.sql"])}|true' for n in selected)
            need(sorted(rows)==expected,'Migration ledger/checksum mismatch (including failed/duplicate entries)')
        materialize(set(names[:44]));prisma('first-44','migrate','deploy');ledger(names[:44])
        gate=f'''SELECT (to_regclass('public."TutoringSessionDocument"') IS NOT NULL), (to_regclass('public."{ORIGINAL}"') IS NOT NULL), (to_regclass('public."{OLD}"') IS NULL), (to_regclass('public."{NEW}"') IS NULL), NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='TutoringSessionDocument' AND column_name='ownerKey');'''
        need(query(db,gate)=='t|t|t|t|t','Historical preconditions not satisfied');print('HISTORICAL_PRECONDITIONS=PASS',flush=True)
        materialize({FAILED});prisma('resolve-premature-rename','migrate','resolve','--applied',FAILED);ledger(names[:45])
        materialize(set(names[45:]));prisma('remaining-66','migrate','deploy');ledger(names)
        index_sql=f'''SELECT count(*) FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_class t ON t.oid=i.indrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='public' AND t.relname='TutoringSessionDocument' AND c.relname='{NEW}' AND i.indisunique AND i.indisvalid AND i.indisready AND i.indpred IS NULL AND i.indexprs IS NULL AND i.indnkeyatts=5 AND (SELECT array_agg(a.attname::text ORDER BY k.ord) FROM unnest(i.indkey) WITH ORDINALITY k(attnum,ord) JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum=k.attnum WHERE k.ord<=i.indnkeyatts)=ARRAY['sessionId','ownerKey','moduleKey','cardKey','toolId'];'''
        need(query(db,index_sql)=='1','Final unique index invalid')
        prisma('migration-status','migrate','status');prisma('schema-diff','migrate','diff','--from-config-datasource','--to-schema',str(cfgdir/'schema.prisma'),'--exit-code');prisma('repeat-deploy','migrate','deploy');ledger(names)
        print('MIGRATION_CHECKSUMS=PASS (111/111)\nFRESH_BOOTSTRAP=PASS',flush=True)

